void Dump(UnityEngine.Transform t, int depth) {
    string indent = new string(' ', depth * 2);
    string comps = "";
    foreach (var cm in t.GetComponents<UnityEngine.Component>()) comps += cm.GetType().Name + ",";
    Debug.Log(indent + t.name + " comps=" + comps);
    for (int i = 0; i < t.childCount && depth < 3; i++) Dump(t.GetChild(i), depth + 1);
}
